async function main() {
  let created = 0;
  let updated = 0;
  for (const p of posts) {
    const existing = await db.blogPost.findUnique({ where: { slug: p.slug } });
    const data = {
      title: p.title,
      excerpt: p.excerpt,
      body: p.body,
      coverEmoji: p.coverEmoji,
      category: p.category,
      tags: p.tags,
      author: "Nxeon",
      seoTitle: p.seoTitle,
      seoDescription: p.seoDescription,
      published: true,
    };
    if (existing) {
      await db.blogPost.update({
        where: { slug: p.slug },
        // Keep the original publish date on re-runs.
        data: { ...data, publishedAt: existing.publishedAt ?? p.publishedAt },
      });
      updated++;
    } else {
      await db.blogPost.create({
        data: { slug: p.slug, ...data, publishedAt: p.publishedAt },
      });
      created++;
    }
  }

  const total = await db.blogPost.count();
  console.log(
    `VPS blog seed complete — ${created} created, ${updated} updated (this batch: ${posts.length}). Total blog posts in DB: ${total}.`
  );
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => db.$disconnect());

