import type { MetadataRoute } from "next";
import { db } from "@/lib/db";

const APP_URL = process.env.APP_URL ?? "https://revsports.ca";

export const dynamic = "force-dynamic";

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const now = new Date();

  const staticRoutes: Array<{ path: string; priority: number; freq: MetadataRoute.Sitemap[number]["changeFrequency"] }> = [
    { path: "", priority: 1.0, freq: "weekly" },
    { path: "/features", priority: 0.8, freq: "monthly" },
    { path: "/pricing", priority: 0.9, freq: "weekly" },
    { path: "/vps", priority: 0.8, freq: "monthly" },
    { path: "/domains", priority: 0.8, freq: "monthly" },
    { path: "/compare", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-digitalocean", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-hostinger", priority: 0.7, freq: "monthly" },
    { path: "/about", priority: 0.5, freq: "monthly" },
    { path: "/contact", priority: 0.5, freq: "monthly" },
    { path: "/blog", priority: 0.7, freq: "weekly" },
    { path: "/status", priority: 0.4, freq: "daily" },
    { path: "/legal/terms", priority: 0.3, freq: "yearly" },
    { path: "/legal/privacy", priority: 0.3, freq: "yearly" },
    { path: "/legal/aup", priority: 0.3, freq: "yearly" },
    { path: "/legal/sla", priority: 0.3, freq: "yearly" },
  ];

  const entries: MetadataRoute.Sitemap = staticRoutes.map((r) => ({
    url: `${APP_URL}${r.path}`,
    lastModified: now,
    changeFrequency: r.freq,
    priority: r.priority,
  }));

  // Published blog posts (model may not be migrated yet — access defensively).
  try {
    const blogModel = (db as unknown as { blogPost?: { findMany: (a: unknown) => Promise<Array<{ slug: string; updatedAt: Date }>> } }).blogPost;
    const posts = blogModel
      ? await blogModel.findMany({
          where: { published: true },
          select: { slug: true, updatedAt: true },
          orderBy: { publishedAt: "desc" },
        })
      : [];
    for (const p of posts) {
      entries.push({
        url: `${APP_URL}/blog/${p.slug}`,
        lastModified: p.updatedAt,
        changeFrequency: "monthly",
        priority: 0.6,
      });
    }
  } catch {
    // blogPost model not migrated yet — skip.
  }

  return entries;
}
